<script setup lang="ts">
import {ref,watch} from 'vue';import {api} from '../api';import Modal from './Modal.vue';import type {WorkTab} from '../stores';
const props=defineProps<{record:any;tab:WorkTab}>(),emit=defineEmits<{cancel:[];saved:[result:any]}>(),date=ref(props.record.requested_date||''),preview=ref<any>(null),error=ref(''),loading=ref(false);
watch(date,()=>{preview.value=null;error.value='';});
function cancel(){if(!loading.value&&!props.tab.busy)emit('cancel');}
async function inspect(){loading.value=true;error.value='';preview.value=null;try{preview.value=await api('transfers/preview',{method:'POST',body:JSON.stringify({id:props.record.id,effective_date:date.value})});}catch(e){error.value=(e as Error).message;}finally{loading.value=false;}}
async function approveSide(){if(props.tab.busy)return;props.tab.busy=true;error.value='';try{const result=await api('transfers/confirm',{method:'POST',body:JSON.stringify({id:props.record.id})});emit('saved',result);}catch(e){error.value=(e as Error).message;}finally{props.tab.busy=false;}}
async function save(){if(!preview.value?.canSubmit||props.tab.busy)return;props.tab.busy=true;error.value='';try{const result=await api('transfers/confirm',{method:'POST',body:JSON.stringify({id:props.record.id,effective_date:date.value,version:preview.value.version})});emit('saved',result);}catch(e){error.value=(e as Error).message;preview.value=null;}finally{props.tab.busy=false;}}
</script>
<template><Modal title="確認調店生效" @cancel="cancel"><p><strong>{{record.employee_code}} {{record.employee_name}}</strong></p><p>{{record.from_store?.store_name}} → {{record.to_store?.store_name}}</p><div class="sides"><div v-for="side in (['from','to'] as const)" :key="side"><strong>{{side==='from'?'原店':'新店'}}督導</strong>：<template v-if="record.confirmations?.[side]?.confirmed">已確認（{{record.confirmations[side].by_name}}{{record.confirmations[side].proxy?'・系統管理員代確認':''}}）</template><template v-else>待確認<small v-if="record.supervisors?.[side]?.length">（{{record.supervisors[side].join('、')}}）</small><small v-else>（此門市沒有督導，需系統管理員代確認）</small><template v-if="record.mySides?.includes(side)">　← 由您確認</template></template></div></div>
<template v-if="record.willComplete"><p>您確認後兩店督導都已確認，調店即生效。可填寫過去、今天或未來的生效日期；確認後立即更新主檔與下方月資料，並記錄指定生效日，不會等到當天才執行。</p><form @submit.prevent="inspect"><label>生效日期<input v-model="date" type="date" min="1912-01-01" required :disabled="loading||tab.busy"></label><button type="submit" :disabled="loading||tab.busy">{{loading?'正在核對…':'核對調店影響'}}</button></form><p v-if="error" role="alert" class="notice error">{{error}}</p>
<template v-if="preview"><ul v-if="preview.conflicts.length" class="notice error" role="alert"><li v-for="item in preview.conflicts" :key="item">{{item}}</li></ul><template v-else><p>員工主檔將由原門市轉至新門市，並建立調店異動紀錄。</p><p v-if="preview.backdated" class="notice">這是補登過去的調店：只寫入歷史，員工目前狀態仍以最新一筆異動為準，月份名冊依生效日重新計算。</p><p v-if="preview.lockedMonths?.length" class="notice">{{preview.lockedMonths.join('、')}} 已送審或已確認，不會修改，會列入月結頁「需重新確認」清單。</p><div v-if="preview.changes.length" class="module-table"><table><thead><tr><th>月份</th><th>門市</th><th>處理</th><th>天數</th></tr></thead><tbody><tr v-for="(change,i) in preview.changes" :key="i"><td>{{change.year_month}}</td><td>{{change.store_id===record.from_store_id?'調出門市':'調入門市'}}</td><td>{{change.operation==='insert'?'新增':'更新'}}</td><td>{{change.work_days}} / {{change.total_days_in_month}}</td></tr></tbody></table></div><p v-else>目前沒有已初始化、需要同步的人員月資料。</p><p>確認後，上述資料會一起儲存。</p></template></template>
</template><template v-else><p>需原店與新店督導都確認才會生效。您確認後，還要等另一店督導確認；兩側都確認完成時才需要填寫生效日期。</p><p v-if="error" role="alert" class="notice error">{{error}}</p></template>
<div class="dialog-actions"><button :disabled="loading||tab.busy" @click="cancel">返回</button><button v-if="!record.willComplete" class="primary" :disabled="tab.busy||loading" @click="approveSide">{{tab.busy?'正在確認…':'確認我負責的'+(record.mySides||[]).map((x:string)=>x==='from'?'原店':'新店').join('、')+'這一側'}}</button><button v-if="preview?.canSubmit" class="primary" :disabled="tab.busy||loading" @click="save">{{tab.busy?'正在確認…':'確認生效'}}</button></div></Modal></template>
<style scoped>form{display:flex;gap:12px;align-items:end;flex-wrap:wrap}label{display:grid;gap:8px}.module-table{max-height:300px;overflow:auto}.module-table table{min-width:0;width:100%}.module-table th,.module-table td{padding:10px 8px;white-space:normal}li+li{margin-top:8px}.sides{line-height:1.7;margin:8px 0}.sides small{color:var(--muted)}</style>
